// MPR distance by kastorp
//----------------------------------------------------------------------------
//   Finally, I managed to get MPR algorithm working for calculating 
//   the distance between convex solids. It's not as effective as GJK, 
//   but with some tricks, it seems to have good accuracy. 
//   In particular, since MPR natively does not handle cases where 
//   the simplex returns to lower dimensions, I mitigated this by smoothing
//   the solid vertices, and separating the faces in the refinement cycle.
//   Additionally, I tried to optimize the compilation times
//
//----------------------------------------------------------------------------
// ACTIONS:
//    mouse: move shape 
//    space: align shapes
//    1-2-3 toggle views
//    c: debug distance iterations
//    d: switch distance source
//----------------------------------------------------------------------------

#define ZERO min(iFrame,0)
#define VAXIS vec3(0,1,0)
#define NOHIT 1e30

struct obj{
    vec3 c; //center
    vec4 b; //bounding box (w=thickness)
    mat3 rm; //rotation (xyz=axis, w=angle)
    int s; //shape 
    int id; //material id
};


struct simplex{
    vec3 a,b,c,d; //simplex
};


//-----------------------------------------------------------------
//SUPPORT FUNCTION

vec3 supMax(vec3 d, vec3 a, vec3 b){ return dot(d,a) > dot(d,b) ? a : b;}

vec3 support(vec3 dir, obj o){

    vec2 dirH=normalize(dir.xy);
    const float phi=(sqrt(5.)-1.)*.5,phi2=phi*phi;

    vec3 s;
    switch (o.s) {
        default:                
        case -1:
            s= vec3(0);          
            break;
        case 0: //BOX
            s=sign(dir)*o.b.xyz;

            break;
        case 1: //ELLIPSOID
            s= normalize(dir*o.b.xyz)*(o.b.xyz);
           break;
        case 2: //CYLINDER
           s=supMax( dir,        
            vec3(normalize(dir.xy*o.b.x)*(o.b.x), o.b.y), 
            vec3(normalize(dir.xy*o.b.x)*(o.b.x), -o.b.y) 
            );
           break;   
        case 3: //CONE
           s=supMax( dir,        
            vec3(dirH*o.b.x, -o.b.z) ,
            vec3(0,0,o.b.z)
            );
           break;                    
        case 4: //TETRAHEDRON
              s=  supMax(dir,
                          supMax( dir,vec3(o.b),vec3(o.b.x,-o.b.yz)),
                          supMax( dir,vec3(-o.b.x,o.b.y,-o.b.z),vec3(-o.b.xy,o.b.z))
                      );
              break;
        case 5: //ICOSAHEDRON
                //h=0.  Tetradecahedron
              s=  o.b.xyz/(1.+phi)* supMax(dir,
                         sign(dir)*vec3(1.,1.+phi,0),
                         supMax(dir, sign(dir)*vec3(0,1.,1.+phi),sign(dir)*vec3(1.+phi,0,1.))
                      );             
              break;
        case 6: //DODECAHEDRON
               //h=1. romboid dodecahedron                      
              s=  o.b.xyz/(1.+phi)* supMax(dir,
                         supMax(dir, sign(dir)*(1.),sign(dir)*vec3(1.+ phi,1.-phi2,0)),
                         supMax(dir, sign(dir)*vec3(0,1. +phi,1.-phi2),sign(dir)*vec3(1.-phi2,0,1.+ phi))
                      );
             break;
        case 8: //SEGMENT
           s=supMax( dir,        
            vec3(o.b.xyz),
            vec3(-o.b.xyz)
            ); 
           break;           

    } 

    return s + normalize(dir)*o.b.w ;
} 

//---------------------------------------------------------
// HELPERS

float dot2( in vec3 v ) { return dot(v,v); }

//helper: baricentric coordinates of closest point to triangle
vec3   PointTriDistK(in vec3 p,  in vec3 b, in vec3 c, in vec3 d)
{
    float k1,k2,k3;	
    vec3 v10 = c - b; vec3 p0 = p - b;
    vec3 v21 = d - c; vec3 p1 = p - c;
    vec3 v02 = b - d; vec3 p2 = p - d;
    vec3 nor = cross( v10, v02 );

         if( dot(cross(v10,nor),p0)<0.0 ) { k2= clamp( dot(p0,v10)/dot2(v10), 0.0, 1.0 ); k3=0.;k1=1.-k2;}
    else if( dot(cross(v21,nor),p1)<0.0 ) { k3= clamp( dot(p1,v21)/dot2(v21), 0.0, 1.0 ); k1=0.;k2=1.-k3;}
    else if( dot(cross(v02,nor),p2)<0.0 ) { k1= clamp( dot(p2,v02)/dot2(v02), 0.0, 1.0 ); k2=0.;k3=1.-k1;}
    else {    
        k1 = dot(cross(c,d),nor);  
        k2 = dot(cross(d,b),nor);  
        k3 = dot(cross(b,c),nor);
    }
    return vec3(k1,k2,k3)/(k1+k2+k3);  
}

//helper: triangle/point distance
float  PointTriDist2(in vec3 p,  in vec3 v0, in vec3 v1, in vec3 v2, out vec3 dir  )
{
//
//    vec3 k = PointTriDistK( p,   v0,v1,v2);
//    vec3 cp= v0*k.x+v1*k.y+v2*k.z;
//    return dot(p-cp,p-cp);
    vec3 v10 = v1 - v0; vec3 p0 = p - v0;
    vec3 v21 = v2 - v1; vec3 p1 = p - v1;
    vec3 v02 = v0 - v2; vec3 p2 = p - v2;
    vec3 nor = cross( v10, v02 );

         if( dot(cross(v10,nor),p0)<0.0 ) dir= v0 + v10*clamp( dot(p0,v10)/dot2(v10), 0.0, 1.0 );
    else if( dot(cross(v21,nor),p1)<0.0 ) dir= v1 + v21*clamp( dot(p1,v21)/dot2(v21), 0.0, 1.0 );
    else if( dot(cross(v02,nor),p2)<0.0 ) dir= v2 + v02*clamp( dot(p2,v02)/dot2(v02), 0.0, 1.0 );
    else dir= p - nor*dot(nor,p0)/dot2(nor);
    return dot2(p-dir);  
}


//---------------------------------------------------------
// DISTANCE between objects
//
// could be extended to do both distance or penetration
//-----------------------------------------------------------
int MPRDist( obj o1,  obj o2 , out vec3 v1, out vec3 v2, out int inside,out simplex s1, out simplex s2,out int iter)
{

    // distance configuration parameters
    #define MAX_ITER 15
    #define TOLERANCE 1e-7
    #define EPS 0.001 
    #define COPLANAR

    vec3[3] a,b,c,d,s;
    #define copy(c,d) {c[0]=d[0];c[1]=d[1];c[2]=d[2]; }
    #define swap(b,c) vec3 t =b[0]; b[0]=c[0];c[0]=t; t =b[1]; b[1]=c[1];c[1]=t; t =b[2];b[2]=c[2];c[2]=t

    vec3 dir;
    inside=0; //if true, origin is inside
    int st=0; //phase
    for(st=ZERO;st<=3;st++){

        vec3[3] v;
         iter=ZERO;
        while(iter<(st<=1?1:MAX_ITER)){

            //BEGIN PRE
            if(st==0){
                dir= vec3(0,1,0);   
                a[1]=o1.c;a[2]=-o2.c; a[0]= a[1]+a[2]; 
                if (a[0]==vec3(0)) {a[1]+= vec3(1e-3,0,0); a[0]+=vec3(1e-3,0,0);}
                dir= -normalize(a[0]); 
            }
            if(st==1){
                copy(b,s);
                if ( dot(b[0], dir) <=0.) inside= -1;

                dir = normalize(cross(a[0], b[0]));					 					   
               if (length(dir)==0.){
               //    inside=true;
               //    if (b[0] == (o1.c-o2.c)) {                       
               //        dir= vec3(0,1,0);                         
               //        return 1;
               //    }
               //    else {                                             
               //         dir =normalize(b[0]);
               //         return 2;
               //    }
               }
            }
            if(st==3){
                dir= normalize(cross( c[0]-b[0], d[0]-b[0])); 
                if ( dot(dir, b[0])>= 0. &&inside==0) inside=1;
            }
            //END PRE

            //Minkowsky difference support function
            //dir=normalize(dir);
            s[1] = support(transpose(o1.rm)*dir,o1)  *transpose(o1.rm) +o1.c ;      
            s[2] = support(-transpose(o2.rm)*dir,o2) *transpose(o2.rm) +o2.c ;   
            //if(o2.b.w==0.) 
            if(o2.s!=-1) s[1]+=EPS *normalize(dir);
            s[0] =s[1]-s[2] ;

            //BEGIN POST
            if(st==1){    
                copy(c,s);  
                if ( dot(c[0], dir) <=0.) inside= -1;  

                dir= normalize(cross(b[0]-a[0],c[0]-a[0]));
                if (dot(dir, a[0]) > 0.){
                    swap(b,c);
                    dir *=-1.;
                }
            }
            if(st==2){    
                copy(d,s);
                if (dot(d[0], dir) <=0.) inside =-1;

                if ( dot(cross (b[0],d[0]), a[0])  < 0. )copy(c,d)
                else if (dot(cross (d[0],c[0]), a[0]) < 0. )copy(b,d)
                else break; //next phase

                dir =normalize(cross( b[0]-a[0], c[0]-a[0]));
                if(iter>8) break;

            }
            if(st==3){    
                copy(v,s);


                float dv4 = dot(v[0], dir);
                 if (dv4 <0. && inside==0 ) inside= -1;
                float dv1 = dot(b[0], dir);
                float dv2 = dot(c[0], dir);
                float dv3 = dot(d[0], dir);        
                bool portalReachTolerance=   (min(min(dv4 - dv1, dv4 - dv2),dv4 - dv3)  <= TOLERANCE);
                if(portalReachTolerance) break;

               #ifdef COPLANAR
                 //this is slow but handles coplanar faces (ie: box, dodecahedron)

                  vec3 e, sd=vec3(
                   PointTriDist2(EPS*(b[0]-v[0]), c[0],  d[0], v[0], e),
                   PointTriDist2(EPS*(d[0]-v[0]), b[0],  c[0], v[0], e),
                   PointTriDist2(EPS*(c[0]-v[0]), d[0],  b[0], v[0], e)
                  );

                  sd=step(sd,sd.yzx)*step(sd,sd.zxy);
                  if (sd.y>0.) copy(d,v)
                  else if (sd.x>0.) copy(b,v)
                  else if (sd.z>0.)  copy(c,v)
              #else
                   //  this is quite faster but still not as accurate        

                   vec3 ncd=normalize(cross( v[0]-c[0],v[0]-d[0]));
                   vec3 nbc=normalize(cross( v[0]-b[0],v[0]-c[0]));
                   vec3 ndb=normalize(cross( v[0]-d[0],v[0]-b[0]));

                   vec3 sd= (vec3( 
                      dot(v[0],ncd),
                      dot(v[0],ndb),
                      dot(v[0],nbc)
                   ));

                 sd=step(sd,sd.yzx)*step(sd,sd.zxy);
                 if (sd.x>0.) copy(b,v)
                 else if (sd.y>0.) copy(c,v)
                 else if (sd.z>0.)  copy(d,v)
               #endif
            }            
            //END POST

            iter++;
            continue;
        }
    }   

    vec3 k =  PointTriDistK(vec3(0),b[0],c[0],d[0]);   
    v1=  (b[1]*k.x+c[1]*k.y+d[1]*k.z) ;
    v2=  (b[2]*k.x+c[2]*k.y+d[2]*k.z) ;

    s1.b=b[1];s1.c=c[1];s1.d=d[1];
    s2.b=b[2];s2.c=c[2];s2.d=d[2];

    return 0;
}


//-------------------------------------------------
// SUPPORT FUNCTION RAY INTERSECTION 
//
//   Given vm as view matrix, casts ray from ro, and estimates depth and normal 
//   
//---------------------------------------------------
float iSupportFunction(  vec3 ro,  mat3 vm, inout obj o, out vec3 normal)
{   
    vec3 dir, tmp;   
    vec3 a,b,c,d;

    float d0=- dot(ro,vm[2]);
    ro*=vm;

    #define ITERATIONS 20
    #define perp2d(v)  ((v).yx*vec2(-1,1))  //(cross(v,vec3(0,0,-1)).xy) 
    a=vec3(ro.xy, 0);

    dir=vec3(-a.xy, 0.);
    for(int st=0;st<3;st++){  
      int N=0; if(st>0) N=ITERATIONS;
      for (int i = ZERO;i <=N; i++){


        vec3 sd=dir*transpose(vm)*o.rm;
        d= -support(-sd, o);
        d=d*transpose(o.rm)*vm;d+=vec3(ro.xy, 0);

        if(st==0){              
                b=d;
                if (dot(-a.xy, b.xy) <= 0.) return NOHIT;
                dir = vec3(perp2d(b-a),0.);
                if (dot(dir.xy, a.xy) >= 0.) {  dir.xy *= -1.; tmp = a; a = b; b = tmp;}            
        }
        else if(st==1){            
                c=d;
                if (dot(c.xy, dir.xy) <= 0.) return (NOHIT);                    
                if (i == 5) return (NOHIT);
                if (dot(dir.xy = perp2d(c-a), c.xy) < 0.) {b = c;}
                else if (dot(dir.xy = perp2d(b-c), c.xy) < 0.)  {a = c;}
                else break;       
        }
        else if(st==2){               
                if (abs(dot(dir, d) - dot(dir, a)) < TOLERANCE) break;
                vec3 abc = step(vec3(0),vec3(
                        dot(perp2d(d-a), d.xy) ,
                        dot(perp2d(d-b), d.xy) ,
                        dot(perp2d(d-c), d.xy)));
                abc= abc* (1.-abc.yzx) ;

                c = abc.x>0.? d:c;
                a = abc.y>0.? d:a;
                b = abc.z>0.? d:b;

                dir = normalize(cross(b-a, c-a));  
        }
      }
    }
    normal = -normalize(cross(b-a, c-a)) ;
    float depth = a.z + dot(a.xy, normal.xy)/normal.z ;   
    normal=normal*transpose(vm);
    return  (  -depth +d0);   
}


//-------------------------------------------------------
// scene and rendering


obj  o1,o2,o3;
vec3 va,vb; //distance vector

int res_distance;

mat3 M_ID=mat3(1,0,0,0,1,0,0,0,1);

obj segment(vec3 v1, vec3 v2, float tk,int id){
    vec3 c = (v1+v2)*.5;
    vec3 b = (v2-v1)*.5;
    return  obj(c,vec4(b,tk),M_ID,8,id);
}


float trace(vec3 ro, vec3 rd, out vec3 nor, out int id){

    id=0;
    obj[] o =  obj[](     
        o1,
        o2,
        segment(va,vb,.005,res_distance<0?6:5),
        obj( vec3(0,-.5,0),  vec4(2.,.01,1,0),M_ID,0, 4)
     );


    vec3 rx =normalize(cross(rd,VAXIS)),ry=cross(rx,rd); 
    mat3 vm=mat3(rx,ry,rd);

    float dist=NOHIT;    
    for(int i=min(0,iFrame);i<o.length();i++){
        vec3 n;   
        obj oo=o[i];
        float t= iSupportFunction( ro -oo.c , vm, oo ,n);

        if(  t <dist   ){               
              nor=-n;
              id=oo.id; 
              dist=t;    
         }
    }
    return dist;
}




mat3 aa2m(vec4 aa){
    float c =cos(aa.w), s = sin(aa.w), t =1. - c;
    return outerProduct(aa.xyz,aa.xyz)*t +
        + mat3 ( c, -aa.z*s, aa.y*s, aa.z*s, c, -aa.x*s, -aa.y*s, aa.x*s, c);
}
vec4 m2aa(mat3 m) {//singularities not handled
    #define mm(a,b) (m[a][b] - m[b][a]) 
    return vec4(normalize(vec3(mm(2,1), mm(0,2), mm(1,0))),
                acos(( m[0][0] + m[1][1] + m[2][2] - 1.)/2.)); 
}

void mainImage(out vec4 O, in vec2 I) {

    vec2 uv = (I - 0.5 * iResolution.xy) / iResolution.y;
    vec2 M = iMouse.z>0.?(iMouse.xy - 0.5 * iResolution.xy) / iResolution.y:vec2(iTime*.2,0.5);
    float tm = .5*iTime;

    vec3   ro= vec3(sin(tm),.5,cos(tm));
    //alternate views (toggle with 1-2-3)
    if(texelFetch(iChannel3,ivec2(49,2),0).x>.5 ) ro= vec3(-1,0,0.001);  
    if(texelFetch(iChannel3,ivec2(50,2),0).x>.5 ) ro= vec3(.001,0,1);  
    if(texelFetch(iChannel3,ivec2(51,2),0).x>.5 ) ro = vec3(0,1,0.001);  

     vec3 rd0 =-normalize(ro); 
     vec3 rx =normalize(cross(rd0,VAXIS)),
          ry =cross(rx,rd0);
     vec3 rd=normalize(rd0+uv.x*rx+uv.y*ry); 


     o1=  obj(  vec3(-.3,0,0) + (iMouse.z>0.?   M.x*rx +M.y*ry:vec3(0)), vec4(.3,.03,.03,0.),
              aa2m(vec4(normalize(vec3(1,1,0)),0.5*tm)),
              0, 1 );

     o2=  obj( vec3(.3,0,0), vec4(.2,.2,.2,.0),
              aa2m(vec4(normalize(vec3(0,1,1)),tm)),
              0 ,2);

    float ch =mod(tm/3.,6.);
    o2.s = int(ch);

    if(texelFetch(iChannel3,ivec2(32,2),0).x>.5) o2.rm=o1.rm; //align

    simplex s1,s2;
    int collision;
    int iter=0;
    res_distance  = MPRDist(o1,o2,va,vb,collision,s1,s2,iter);

    O=vec4(1);
    int res_pen=-1;


    //PALETTE:
    vec3[] cols =vec3[] (vec3(0),vec3(1,0,0),vec3(0,0,1),vec3(0,1,0),vec3(.5),vec3(1),vec3(1,1,0),vec3(1,0,1),vec3(0,1,1));
    vec3 nor;

    int id,id2;
    float dist=trace(ro,rd,nor,id);

    if (dist<NOHIT){
       vec3 ld=normalize(vec3(1,3,.5));
       //nor=-ld;
       vec3 pos=ro+rd*dist;
       float gr =  max(max(sin(pos.x*62.8),sin(pos.y*62.8)),sin(pos.z*62.8));
       vec3 col= cols[id];

       if(id==1) {      
           if(min(min(length(pos-s1.d), length(pos-s1.b)), length(pos-s1.c))<.02) col=vec3(1,1,0);
       }
       if(id==2) {      
           if(min(min(length(pos-s2.d), length(pos-s2.b)), length(pos-s2.c))<.02) col=vec3(0,1,1);
       }

       O = vec4(col,1.) * (.9+ smoothstep(1.,1.-min(fwidth(gr),.1),gr)*.1) *(1.- dot(nor,ld))*.5;

      //if(texelFetch(iChannel3,ivec2(66,2),0).x<.5){
      //    vec3 n2;
      //     bool sh = trace(ro+rd*(dist-.001),ld,n2,id2)<NOHIT ;
      //     if(sh )O*=.5;
      //}


       o3=  obj( pos, vec4(0), M_ID,-1,2);

    } 
    else{
        O=vec4(.2);
         o3= segment(ro-rd*5., ro+rd*5., .0,5);

    }

    if(collision>0) O.x*=2.;    

    if(texelFetch(iChannel3,ivec2(68,2),0).x>.5) o1=o2;
   int res= MPRDist(o1,o3,va,vb,collision,s1,s2,iter); 
   if(texelFetch(iChannel3,ivec2(67,2),0).x>.5 && collision<=0)
       O*=.1+vec4(iter)/10.; //DEBUG ITERATIONS
   else
       O+= .2*smoothstep(-.1,.1,sin(length(va-vb)*62.8))*(res<0?vec4(2,2,0,0):vec4(1));

}
